package ro.leo.visual;
import ro.leo.i18n.L;import android.os.Bundle;import java.util.*;import org.json.*;
public final class AutomationsActivity extends LeoActivity {
 static final String[] TRIGGERS=L.array(new String[]{"Căști conectate","Încărcător conectat","Wi-Fi conectat","Bluetooth conectat"});static final String[] ACTIONS=L.array(new String[]{"Notificare pentru Muzică","Profil Noapte","Profil Normal","Memento local"});
 protected void onCreate(Bundle b){super.onCreate(b);show();}
 void show(){final JSONArray rows=AutomationRules.read(AutomationsActivity.this);ArrayList<String> labels=new ArrayList<String>();labels.add(L.t("Regulă nouă"));labels.add(getSharedPreferences("automation",0).getString("last-result",L.t("Nicio regulă executată")));for(int n=0;n<rows.length();n++){JSONObject r=rows.optJSONObject(n);labels.add((r.optBoolean("enabled")?"● ":"○ ")+r.optString("event")+" → "+r.optString("action"));}list(L.t("Automatizări locale"),labels,0,new Choice(){public void pick(final int n){if(n==0)add();else if(n>=2)edit(rows,n-2);}},"",null);}
 void add(){if(AutomationRules.read(AutomationsActivity.this).length()>=16){notice("Maximum 16");return;}options(L.t("Când se întâmplă"),TRIGGERS,new Choice(){public void pick(final int event){options(L.t("Acțiune locală"),ACTIONS,new Choice(){public void pick(final int action){try{JSONArray rows=AutomationRules.read(AutomationsActivity.this);rows.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("event",AutomationRules.EVENTS[event]).put("action",AutomationRules.ACTIONS[action]).put("enabled",false));AutomationRules.save(AutomationsActivity.this,rows);notice(L.t("Regulă creată oprită · activeaz-o explicit"));show();}catch(Exception e){notice(L.t("Regulă nesalvată"));}}});}});}
 void edit(final JSONArray rows,final int index){options(L.t("Regulă locală"),new String[]{L.t("Activează / oprește"),L.t("Șterge regula")},new Choice(){public void pick(final int n){try{if(n==0){JSONObject r=rows.getJSONObject(index);r.put("enabled",!r.optBoolean("enabled"));}else rows.remove(index);AutomationRules.save(AutomationsActivity.this,rows);show();}catch(Exception e){notice(L.t("Regulă nesalvată"));}}});}
}
